def generate_graph_file(user_info):
    with open("graph.txt", "w") as f:
        f.write(f"user: {user_info}\n")

def main():
    user_info = extract_user_info("user.txt")
    if user_info:
        generate_log_file(user_info)
        generate_graph_file(user_info)
    else:
        print("No user information found.")

if __name__ == "__main__":
